def analyze_transformations(inputs, outputs):
    """Analyze what transformations occur between inputs and outputs"""
    print("Input -> Output analysis:")
    for i, (inp, out) in enumerate(zip(inputs, outputs)):
        print(f"{inp} -> {out}")

        # Find differences
        diff_pairs = []
        min_len = min(len(inp), len(out))
        for j in range(min_len):
            if inp[j] != out[j]:
                diff_pairs.append((inp[j], out[j]))

        # Check remaining chars
        if len(inp) > len(out):
            for j in range(len(out), len(inp)):
                diff_pairs.append((inp[j], None))
        elif len(out) > len(inp):
            for j in range(len(inp), len(out)):
                diff_pairs.append((None, out[j]))

        print(f"  Differences: {diff_pairs}")
        print()

inputs = ['vdaxj', 'gx', 'kuz', 'hgakk', 'cuveky']
outputs = ['vyexy', 'gx', 'kubj', 'hgbyckk', 'cuveky']
analyze_transformations(inputs, outputs)

