# Let me work backwards from the expected outputs to understand the exact changes
inputs = ['vdaxj', 'gx', 'kuz', 'hgakk', 'cuveky']
outputs = ['vyexy', 'gx', 'kubj', 'hgbyckk', 'cuveky']

# Analyze each pair to identify exact character substitutions
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"Example {i+1}: '{inp}' -> '{out}'")

    # Create mapping of what changed
    changes = []
    min_len = min(len(inp), len(out))

    # Check character by character
    for j in range(min_len):
        if inp[j] != out[j]:
            changes.append(f"'{inp[j]}' -> '{out[j]}'")

    # Handle length differences
    if len(inp) > len(out):
        for j in range(len(out), len(inp)):
            changes.append(f"'{inp[j]}' removed")
    elif len(out) > len(inp):
        for j in range(len(inp), len(out)):
            changes.append(f"added '{out[j]}'")

    print(f"  Changes: {changes}")
    print()

